-- The setup code a new install is claimed with, generated by whichever server needs it first and
-- kept here until the first account exists, so that every server checks against the same code and
-- prints the same one. At most one row. Not used when app.setup.code sets the code.
CREATE TABLE setup_code (
    id smallint NOT NULL DEFAULT 1,
    code character varying(32) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT setup_code_pkey PRIMARY KEY (id),
    CONSTRAINT setup_code_one_row CHECK (id = 1)
);
